<?php
/** Authenticated REST workflow for AI proposals and human reviews. */

if ( ! defined( 'ABSPATH' ) ) { exit; }

class InfoContainer_AI_REST_API {
	const REST_NAMESPACE='infocontainer/v1'; const MAX_IMAGES=12; const MAX_TOTAL_BYTES=31457280; const UUID='/\A[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\z/i';
	private $repository; private $client; private $storage; private $photos;
	public function __construct(InfoContainer_AI_Repository $repository,InfoContainer_OpenAI_Client $client,InfoContainer_Photo_Storage $storage,InfoContainer_Photo_Repository $photos){$this->repository=$repository;$this->client=$client;$this->storage=$storage;$this->photos=$photos;}
	public function register_routes(){
		$p=array($this,'check_permissions');
		register_rest_route(self::REST_NAMESPACE,'/ai/identifications',array('methods'=>'POST','callback'=>array($this,'identify'),'permission_callback'=>$p));
		register_rest_route(self::REST_NAMESPACE,'/inspections/(?P<id>[0-9]+)/ai-analyses',array('methods'=>'POST','callback'=>array($this,'analyze'),'permission_callback'=>$p));
		register_rest_route(self::REST_NAMESPACE,'/ai/runs/(?P<id>[0-9]+)',array('methods'=>'GET','callback'=>array($this,'get_run'),'permission_callback'=>$p));
		register_rest_route(self::REST_NAMESPACE,'/inspections/(?P<id>[0-9]+)/ai-runs',array('methods'=>'GET','callback'=>array($this,'list_runs'),'permission_callback'=>$p));
		register_rest_route(self::REST_NAMESPACE,'/ai/runs/(?P<id>[0-9]+)/reviews',array('methods'=>'POST','callback'=>array($this,'review'),'permission_callback'=>$p));
	}
	public function check_permissions(){if(!is_user_logged_in())return new WP_Error('infocontainer_authentication_required',__('Debes autenticarte para usar InfoContainer.','infocontainer'),array('status'=>401));if(!current_user_can(InfoContainer_Install::CAPABILITY))return new WP_Error('infocontainer_forbidden',__('No tienes permiso para usar InfoContainer.','infocontainer'),array('status'=>403));$error=InfoContainer_Install::get_error();return is_wp_error($error)?$error:true;}

	public function identify(WP_REST_Request $request){
		$data=$this->multipart($request);if(is_wp_error($data))return $data;
		$validated=$this->storage->validate_upload($request->get_file_params()['file']);if(is_wp_error($validated))return $validated;
		$this->storage->cleanup_ai_temporaries();
		$key=$this->storage->store_temporary($validated);if(is_wp_error($key))return $key;
		$handle=null;
		try{
			$snapshot=array('operation'=>'identification','image'=>array('sha256'=>$validated['sha256'],'mime_type'=>$validated['mime_type'],'byte_size'=>$validated['byte_size'],'width'=>$validated['width'],'height'=>$validated['height']));
			$fingerprint=$this->fingerprint($snapshot);
			$reserved=$this->repository->reserve(array('operation'=>'identification','inspection_id'=>null,'client_request_id'=>$data['client_request_id'],'model_configured'=>$this->client->configured_model(),'input_fingerprint'=>$fingerprint,'input_snapshot'=>$snapshot,'source_fingerprint'=>$fingerprint));
			if(is_wp_error($reserved))return $reserved;if(!$reserved['created'])return $this->run_response($reserved['run'],200);
			$opened=$this->storage->open($key);if(is_wp_error($opened)){ $this->repository->fail($reserved['run']['id'],$opened);return $opened;}$handle=$opened;
			$result=$this->client->request('identification',array(array('handle'=>$handle,'byte_size'=>$validated['byte_size'],'mime_type'=>$validated['mime_type'],'category'=>'identifier')),array('human_confirmation_required'=>true));
			if(is_wp_error($result)){ $run=$this->repository->fail($reserved['run']['id'],$result);return is_wp_error($run)?$run:$this->run_response($run,$this->error_status($result));}
			$proposal=InfoContainer_AI_Schemas::validate_identification($result['proposal']);if(is_wp_error($proposal)){ $run=$this->repository->fail($reserved['run']['id'],$proposal);return $this->run_response($run,502);}
			$run=$this->repository->complete($reserved['run']['id'],$result,$proposal);return is_wp_error($run)?$run:$this->run_response($run,201);
		}finally{if(is_resource($handle))fclose($handle);$this->storage->delete($key);}
	}

	public function analyze(WP_REST_Request $request){
		$id=$this->id($request,array());if(is_wp_error($id))return $id;$data=$this->json($request,array('client_request_id','photo_ids'));if(is_wp_error($data))return $data;$uuid=$this->uuid(isset($data['client_request_id'])?$data['client_request_id']:null,'client_request_id');if(is_wp_error($uuid))return $uuid;
		$inspection=$this->photos->get_inspection($id);if(is_wp_error($inspection))return $inspection;if('draft'!==$inspection['status'])return new WP_Error('infocontainer_inspection_not_draft',__('La inspeccion debe seguir en borrador para solicitar el analisis.','infocontainer'),array('status'=>409));
		$all=$this->all_photos($id);if(is_wp_error($all))return $all;
		if(!array_key_exists('photo_ids',$data)){if(count($all)>self::MAX_IMAGES)return $this->invalid('Selecciona explicitamente hasta 12 photo_ids.');$selected=$all;}else{$selected=$this->select_photos($data['photo_ids'],$all);if(is_wp_error($selected))return $selected;}
		if(empty($selected))return $this->invalid('El analisis necesita al menos una fotografia.');if(count($selected)>self::MAX_IMAGES)return new WP_Error('infocontainer_ai_image_limit',__('Cada analisis admite hasta 12 fotografias.','infocontainer'),array('status'=>413));
		usort($selected,function($a,$b){return(int)$a['id']<=>(int)$b['id'];});usort($all,function($a,$b){return(int)$a['id']<=>(int)$b['id'];});$total=0;$photo_snapshot=array();foreach($selected as $photo){$total+=(int)$photo['byte_size'];$photo_snapshot[]=$this->snapshot_photo($photo);}$collection_snapshot=array();foreach($all as $photo)$collection_snapshot[]=$this->snapshot_photo($photo);
		if($total>self::MAX_TOTAL_BYTES||memory_get_usage(true)+(int)ceil($total*1.5)>134217728)return new WP_Error('infocontainer_ai_image_budget',__('Las imagenes superan el presupuesto de bytes o memoria del analisis.','infocontainer'),array('status'=>413));
		$snapshot=array('operation'=>'inspection_analysis','inspection'=>array('id'=>(int)$inspection['id'],'container_id'=>(int)$inspection['container_id'],'identifier_snapshot'=>$inspection['identifier_snapshot'],'iso_code_snapshot'=>$inspection['iso_code_snapshot'],'inspection_type'=>$inspection['inspection_type'],'inspected_at_utc'=>$inspection['inspected_at_utc'],'observations'=>$inspection['observations'],'status'=>$inspection['status']),'photos'=>$collection_snapshot,'selected_photo_ids'=>array_map(function($p){return(int)$p['id'];},$selected));
		$fingerprint=$this->fingerprint($snapshot);$reserved=$this->repository->reserve(array('operation'=>'inspection_analysis','inspection_id'=>$id,'client_request_id'=>$uuid,'model_configured'=>$this->client->configured_model(),'input_fingerprint'=>$fingerprint,'input_snapshot'=>$snapshot,'source_fingerprint'=>$fingerprint));if(is_wp_error($reserved))return $reserved;if(!$reserved['created'])return $this->run_response($reserved['run'],200);
		$images=array();$handles=array();try{foreach($selected as$photo){$opened=$this->storage->open($photo['storage_key']);if(is_wp_error($opened)){ $this->repository->fail($reserved['run']['id'],$opened);return $opened;}$handles[]=$opened;$images[]=array('handle'=>$opened,'byte_size'=>(int)$photo['byte_size'],'mime_type'=>$photo['mime_type'],'category'=>$photo['category'],'photo_id'=>(int)$photo['id']);}
			$context=array('inspection'=>$snapshot['inspection'],'photos'=>array_map(function($p){return array('photo_id'=>$p['id'],'category'=>$p['category'],'operator_description'=>$p['description']);},$photo_snapshot),'nominal_iso_type'=>InfoContainer_AI_Schemas::nominal_iso_type($inspection['iso_code_snapshot']));
			$result=$this->client->request('inspection_analysis',$images,$context);if(is_wp_error($result)){ $run=$this->repository->fail($reserved['run']['id'],$result);return is_wp_error($run)?$run:$this->run_response($run,$this->error_status($result));}
			$allowed=array_map(function($p){return(int)$p['id'];},$selected);$proposal=InfoContainer_AI_Schemas::validate_analysis($result['proposal'],$allowed);if(is_wp_error($proposal)){ $run=$this->repository->fail($reserved['run']['id'],$proposal);return $this->run_response($run,502);}
			$proposal['identifier_comparison']=$this->identifier_comparison($proposal,$inspection['identifier_snapshot']);$run=$this->repository->complete($reserved['run']['id'],$result,$proposal);return is_wp_error($run)?$run:$this->run_response($run,201);
		}finally{foreach($handles as$h)if(is_resource($h))fclose($h);}
	}

	public function get_run(WP_REST_Request $request){$id=$this->id($request);if(is_wp_error($id))return$id;$run=$this->repository->get($id);return is_wp_error($run)?$run:$this->run_response($run,200);}
	public function list_runs(WP_REST_Request $request){$id=$this->id($request,array('page','per_page'));if(is_wp_error($id))return$id;$inspection=$this->photos->get_inspection($id);if(is_wp_error($inspection))return$inspection;$p=$this->pagination($request);if(is_wp_error($p))return$p;$result=$this->repository->list_for_inspection($id,$p['page'],$p['per_page']);if(is_wp_error($result))return$result;$items=array();foreach($result['items']as$row)$items[]=$this->public_run($row);$response=new WP_REST_Response($items,200);$response->header('X-WP-Total',(int)$result['total']);$response->header('X-WP-TotalPages',(int)ceil($result['total']/$p['per_page']));return$response;}
	public function review(WP_REST_Request $request){$id=$this->id($request);if(is_wp_error($id))return$id;$data=$this->json($request,array('client_review_id','action','reviewed_content','identification_resolution'));if(is_wp_error($data))return$data;$uuid=$this->uuid(isset($data['client_review_id'])?$data['client_review_id']:null,'client_review_id');if(is_wp_error($uuid))return$uuid;$action=isset($data['action'])?$data['action']:null;if(!in_array($action,array('accepted','edited','rejected'),true))return$this->invalid('action debe ser accepted, edited o rejected.');$run=$this->repository->get($id);if(is_wp_error($run))return$run;if('completed'!==$run['status'])return new WP_Error('infocontainer_ai_not_completed',__('Solo se puede revisar una ejecucion completada.','infocontainer'),array('status'=>409));
		$current=$this->current_fingerprint($run);if(is_wp_error($current))return$current;$stale=!hash_equals($run['source_fingerprint'],$current);if($stale&&'rejected'!==$action)return new WP_Error('infocontainer_ai_stale',__('La propuesta esta desactualizada porque cambiaron sus fuentes.','infocontainer'),array('status'=>409));
		$content=array_key_exists('reviewed_content',$data)?$data['reviewed_content']:null;if('rejected'===$action){if(null!==$content&&(!is_string($content)||strlen($content)>2000))return$this->invalid('El motivo de rechazo debe ser texto breve o null.');}elseif('identification'===$run['operation']){$content=$this->validate_identification_review($content);if(is_wp_error($content))return$content;}else{$proposal=json_decode($run['proposal'],true);if('edited'===$action){$content=InfoContainer_AI_Schemas::validate_analysis($content,$this->snapshot_photo_ids($run));if(is_wp_error($content))return$content;}else{$content=$proposal;}$comparison=isset($proposal['identifier_comparison'])?$proposal['identifier_comparison']:array('conflict'=>false);if(!empty($comparison['conflict'])){if(!isset($data['identification_resolution'])||!is_string($data['identification_resolution'])||trim($data['identification_resolution'])===''||strlen($data['identification_resolution'])>1000)return$this->invalid('El conflicto de identificacion requiere identification_resolution.');$content=array('proposal'=>$content,'identification_resolution'=>sanitize_textarea_field($data['identification_resolution']));}}
		$result=$this->repository->add_review($id,$uuid,$action,$content,$current);if(is_wp_error($result))return$result;$reviews=$this->repository->list_reviews($id);return new WP_REST_Response(array('review'=>$this->public_review($result['review']),'history'=>array_map(array($this,'public_review'),$reviews)), $result['created']?201:200);
	}

	private function multipart($request){if(!preg_match('#^multipart/form-data(?:\s*;|$)#i',(string)$request->get_header('content-type')))return$this->invalid('Utiliza multipart/form-data.');$files=$request->get_file_params();if(count($files)!==1||!isset($files['file'])||!is_array($files['file']))return$this->invalid('Envia exactamente un archivo en file.');$data=$request->get_body_params();$ok=InfoContainer_Validator::assert_allowed_fields($data,array('client_request_id'));if(is_wp_error($ok))return$ok;$uuid=$this->uuid(isset($data['client_request_id'])?$data['client_request_id']:null,'client_request_id');return is_wp_error($uuid)?$uuid:array('client_request_id'=>$uuid);}
	private function json($request,$allowed){if(!$request->is_json_content_type()||$request->get_file_params()||!is_object(json_decode($request->get_body())))return$this->invalid('El cuerpo debe ser un objeto JSON.');$data=$request->get_json_params();$ok=InfoContainer_Validator::assert_allowed_fields($data,$allowed);return is_wp_error($ok)?$ok:$data;}
	private function uuid($value,$field){return is_string($value)&&preg_match(self::UUID,$value)?strtolower($value):$this->invalid($field.' debe ser un UUID valido con guiones.');}
	private function select_photos($ids,$all){if(!is_array($ids)||count($ids)!==count(array_unique($ids,SORT_REGULAR)))return$this->invalid('photo_ids debe ser una lista sin duplicados.');$map=array();foreach($all as$p)$map[(string)$p['id']]=$p;$out=array();foreach($ids as$id){if(!is_int($id)||$id<1||!isset($map[(string)$id]))return new WP_Error('infocontainer_ai_photo_mismatch',__('Todas las fotografias deben pertenecer a la inspeccion.','infocontainer'),array('status'=>409));$out[]=$map[(string)$id];}return$out;}
	private function fingerprint($value){return hash('sha256',wp_json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
	private function identifier_comparison($proposal,$expected){$values=array();foreach($proposal['visible_readings']as$r)if('identifier'===$r['kind']&&null!==$r['value']){$v=InfoContainer_Validator::identifier($r['value']);$values[]=array('value'=>$r['value'],'valid'=>!is_wp_error($v),'matches_record'=>!is_wp_error($v)&&$v===$expected);} $conflict=false;foreach($values as$v)if($v['valid']&&!$v['matches_record'])$conflict=true;return array('registered_identifier'=>$expected,'readings'=>$values,'conflict'=>$conflict);}
	private function current_fingerprint($run){if('identification'===$run['operation'])return$run['source_fingerprint'];$snapshot=json_decode($run['input_snapshot'],true);if(!is_array($snapshot)||!isset($snapshot['inspection']['id'],$snapshot['photos']))return new WP_Error('infocontainer_ai_snapshot_invalid',__('No se pudo comprobar la vigencia de la propuesta.','infocontainer'),array('status'=>500));$inspection=$this->photos->get_inspection((int)$snapshot['inspection']['id']);if(is_wp_error($inspection))return$inspection;$all=$this->all_photos((int)$inspection['id']);if(is_wp_error($all))return$all;usort($all,function($a,$b){return(int)$a['id']<=>(int)$b['id'];});$photos=array();foreach($all as$p)$photos[]=$this->snapshot_photo($p);$current=array('operation'=>'inspection_analysis','inspection'=>array('id'=>(int)$inspection['id'],'container_id'=>(int)$inspection['container_id'],'identifier_snapshot'=>$inspection['identifier_snapshot'],'iso_code_snapshot'=>$inspection['iso_code_snapshot'],'inspection_type'=>$inspection['inspection_type'],'inspected_at_utc'=>$inspection['inspected_at_utc'],'observations'=>$inspection['observations'],'status'=>$inspection['status']),'photos'=>$photos);if(isset($snapshot['selected_photo_ids']))$current['selected_photo_ids']=array_map('intval',$snapshot['selected_photo_ids']);return$this->fingerprint($current);}
	private function validate_identification_review($content){if(!is_array($content)||count($content)!==2||!array_key_exists('identifier',$content)||!array_key_exists('iso_code',$content))return$this->invalid('reviewed_content debe contener identifier e iso_code.');$identifier=InfoContainer_Validator::identifier($content['identifier']);if(is_wp_error($identifier))return$identifier;$iso=InfoContainer_Validator::iso_code($content['iso_code']);if(is_wp_error($iso))return$iso;return array('identifier'=>$identifier,'iso_code'=>$iso);}
	private function snapshot_photo_ids($run){$s=json_decode($run['input_snapshot'],true);if(isset($s['selected_photo_ids']))return array_map('intval',$s['selected_photo_ids']);return isset($s['photos'])?array_map(function($p){return(int)$p['id'];},$s['photos']):array();}
	private function snapshot_photo($photo){return array('id'=>(int)$photo['id'],'sha256'=>$photo['sha256'],'category'=>$photo['category'],'description'=>$photo['description'],'mime_type'=>$photo['mime_type'],'byte_size'=>(int)$photo['byte_size'],'width'=>(int)$photo['width'],'height'=>(int)$photo['height'],'captured_at_utc'=>$photo['captured_at_utc'],'updated_at_utc'=>$photo['updated_at_utc']);}
	private function all_photos($inspection_id){$first=$this->photos->list_for_inspection($inspection_id,1,100);if(is_wp_error($first))return$first;$items=$first['items'];$pages=(int)ceil($first['total']/100);for($page=2;$page<=$pages;$page++){$next=$this->photos->list_for_inspection($inspection_id,$page,100);if(is_wp_error($next))return$next;$items=array_merge($items,$next['items']);}return$items;}
	private function run_response($run,$status){return new WP_REST_Response($this->public_run($run),$status);}
	private function public_run($run){$proposal=null;if(!empty($run['proposal']))$proposal=json_decode($run['proposal'],true);$usage=!empty($run['usage_json'])?json_decode($run['usage_json'],true):null;$stale=false;if('completed'===$run['status']&&'inspection_analysis'===$run['operation']){$current=$this->current_fingerprint($run);$stale=is_string($current)&&!hash_equals($run['source_fingerprint'],$current);}$public_status=$run['status'];if('processing'===$public_status&&!empty($run['processing_expires_at_utc'])&&strtotime($run['processing_expires_at_utc'].' UTC')<time())$public_status='interrupted';return array('id'=>(int)$run['id'],'operation'=>$run['operation'],'inspection_id'=>null===$run['inspection_id']?null:(int)$run['inspection_id'],'client_request_id'=>$run['client_request_id'],'status'=>$public_status,'processing_expires_at_utc'=>$this->utc($run['processing_expires_at_utc']),'model_configured'=>$run['model_configured'],'model_used'=>$run['model_used']?:null,'prompt_version'=>$run['prompt_version'],'proposal'=>$proposal,'usage'=>$usage,'provider_response_id'=>$run['provider_response_id']?:null,'error'=>''===$run['error_code']?null:array('code'=>$run['error_code'],'message'=>$run['error_message']),'stale'=>$stale,'human_confirmation_required'=>true,'created_by'=>(int)$run['created_by'],'created_at_utc'=>$this->utc($run['created_at_utc']),'updated_at_utc'=>$this->utc($run['updated_at_utc']),'completed_at_utc'=>$this->utc($run['completed_at_utc']));}
	public function public_review($row){$content=null;if(null!==$row['reviewed_content']){$content=json_decode($row['reviewed_content'],true);if(JSON_ERROR_NONE!==json_last_error())$content=$row['reviewed_content'];}return array('id'=>(int)$row['id'],'run_id'=>(int)$row['run_id'],'client_review_id'=>$row['client_review_id'],'reviewed_by'=>(int)$row['reviewed_by'],'action'=>$row['action'],'reviewed_content'=>$content,'created_at_utc'=>$this->utc($row['created_at_utc']));}
	private function id($request,$allowed=array()){$ok=InfoContainer_Validator::assert_allowed_fields($request->get_query_params(),array_merge($allowed,array('_wpnonce','rest_route','_fields','_envelope','_pretty','_locale')));if(is_wp_error($ok))return$ok;$p=$request->get_url_params();return isset($p['id'])&&is_scalar($p['id'])&&preg_match('/^[1-9][0-9]*$/D',(string)$p['id'])?(int)$p['id']:$this->invalid('El ID debe ser un entero positivo.');}
	private function pagination($request){$q=$request->get_query_params();$p=array('page'=>1,'per_page'=>20);foreach($p as$k=>$v)if(isset($q[$k])){if(!is_scalar($q[$k])||!preg_match('/^[1-9][0-9]*$/D',(string)$q[$k]))return$this->invalid('La paginacion debe usar enteros positivos.');$p[$k]=(int)$q[$k];}if($p['per_page']>100)return$this->invalid('per_page admite un maximo de 100.');return$p;}
	private function utc($value){return null===$value?null:str_replace(' ','T',$value).'Z';}
	private function error_status($error){$d=$error->get_error_data();return is_array($d)&&isset($d['status'])?(int)$d['status']:502;}
	private function invalid($message){return new WP_Error('infocontainer_ai_invalid_request',__($message,'infocontainer'),array('status'=>400));}
}
